/* Original task content. No external question bank. */
(function(root){
'use strict';
const TASKS=[
{id:'v1',domain:'representation',dimension:'Coordinates',title:'Read the movement',prompt:'The arrow moves from (0, 0) to (3, −2). Write its horizontal and vertical components.',kind:'pair',labels:['Horizontal component','Vertical component'],u:[3,-2],answer:[3,-2],hint:'A component describes a change: right is positive x; down is negative y.',solution:'From the origin, move 3 right and 2 down. The vector is (3, −2).'},
{id:'v2',domain:'representation',dimension:'Geometry',title:'Place the endpoint',prompt:'A vector starts at the origin. Place its endpoint so that it represents (3, −2).',kind:'drag',math:'v = (3, −2)',answer:[3,-2],hint:'Start at (0, 0). The first component controls horizontal movement; the second controls vertical movement.',solution:'The endpoint belongs at x = 3, y = −2. Coordinates and arrows describe the same movement.'},
{id:'a1',domain:'addition',dimension:'Calculation',title:'Combine two movements',prompt:'Calculate u + v. Give both components of the result.',kind:'pair',labels:['Result x','Result y'],u:[2,1],v:[-1,2],math:'u = (2, 1)     v = (−1, 2)',answer:[1,3],hint:'Add the horizontal changes together, then add the vertical changes together.',solution:'u + v = (2 + (−1), 1 + 2) = (1, 3).'},
{id:'a2',domain:'addition',dimension:'Geometry',title:'Continue from the tip',prompt:'Move 2 right and 1 up. From that new position, move 1 left and 2 up. Place the endpoint of the total movement.',kind:'drag',u:[2,1],v:[-1,2],chain:true,answer:[1,3],hint:'The second movement begins where the first ends. Keep track of the total change from the origin.',solution:'Following both movements ends at (1, 3). The resultant arrow runs from the origin to that endpoint.'},
{id:'s1',domain:'scaling',dimension:'Geometry',title:'Reverse and stretch',prompt:'Place the endpoint of −2u. Then choose the description that matches the change.',kind:'drag-choice',u:[1,2],math:'u = (1, 2)     Find −2u',options:['Same direction, twice as long','Opposite direction, twice as long','Opposite direction, half as long'],answer:[-2,-4],choiceAnswer:1,hint:'The magnitude of a scalar changes length. A negative scalar reverses direction.',solution:'−2u = (−2, −4). The arrow is twice as long and points in the opposite direction.'},
{id:'c1',domain:'combination',dimension:'Construction',title:'Reach the target',prompt:'Use the controls to find a and b so that au + bv reaches w. Coefficients can be positive, zero, or negative.',kind:'coeff',u:[2,1],v:[1,3],target:[5,5],math:'a(2, 1) + b(1, 3) = (5, 5)',answer:[2,1],hint:'A coefficient tells you how many copies of a vector to use. Watch the two component totals as you change a and b.',solution:'a = 2 and b = 1: 2(2, 1) + (1, 3) = (5, 5). Finding one target does not show that every target is reachable.'},
{id:'c2',domain:'combination',dimension:'Reachability',title:'Can you leave the line?',prompt:'Here u = (1, 2) and v = (2, 4). Can any real coefficients a and b make au + bv = (3, 5)? Choose the best explanation.',kind:'choice',u:[1,2],v:[2,4],target:[3,5],dependent:true,options:['Yes. Two arrows always let us reach every point.','No. Both arrows stay on y = 2x, but (3, 5) is off that line.','No. Coefficients are only allowed to be positive.'],answer:1,hint:'Notice that v is two copies of u. What relationship must hold between x and y for every combination?',solution:'Every combination is (a + 2b, 2a + 4b), so y = 2x. At x = 3 that line has y = 6, not 5. Negative coefficients still cannot leave it.'},
{id:'t1',domain:'transfer',dimension:'Equations → vectors',title:'See the system as movement',prompt:'These equations describe the same two coefficients a and b. Which vector statement represents the system?',kind:'choice',math:'a + 2b = 4\n2a + b = 5',u:[1,2],v:[2,1],target:[4,5],options:['a(1, 2) + b(2, 1) = (4, 5)','a(1, 2) + b(2, 1) = (5, 4)','a(1, 1) + b(2, 2) = (4, 5)'],answer:0,hint:'Collect the coefficients of a from both equations to make one vector. Do the same for b. Keep the equation order.',solution:'The a coefficients are (1, 2); the b coefficients are (2, 1); the right-hand sides are (4, 5). Thus a(1, 2) + b(2, 1) = (4, 5).'}
];
const FOLLOWUPS={
representation:{id:'f-r',domain:'representation',dimension:'Transfer to a moved start',title:'An arrow can move',prompt:'An arrow starts at (−1, 1) and ends at (2, −1). What are its components?',kind:'pair',labels:['Horizontal change','Vertical change'],start:[-1,1],u:[3,-2],answer:[3,-2],hint:'Components are endpoint minus starting point. The endpoint alone is not the vector.',solution:'(2 − (−1), −1 − 1) = (3, −2). Changing where an arrow is drawn does not change its components.'},
addition:{id:'f-a',domain:'addition',dimension:'Cancellation',title:'A round trip',prompt:'You move by (2, −1), then by (−2, 1). Where do you end relative to your starting point?',kind:'choice',u:[2,-1],v:[-2,1],options:['At (0, 0): the movements cancel.','At (4, −2): the lengths add in the same direction.','At (−4, 2): the second movement doubles.'],answer:0,hint:'Add each pair of components. Opposite movements can cancel.',solution:'(2, −1) + (−2, 1) = (0, 0). The total displacement is zero.'},
scaling:{id:'f-s',domain:'scaling',dimension:'Zero scaling',title:'What does zero do?',prompt:'For u = (2, −3), which statement correctly describes 0u?',kind:'choice',u:[2,-3],options:['It is (0, 0), with zero length and no direction.','It is (2, −3), since multiplying by zero changes nothing.','It is (−2, 3), since zero reverses the arrow.'],answer:0,hint:'Multiply each component by zero. A vector with zero length has no direction.',solution:'0(2, −3) = (0, 0). Zero scaling collapses the movement to the origin.'},
combination:{id:'f-c',domain:'combination',dimension:'Unrestricted reachability',title:'Two independent directions',prompt:'Let u = (1, 0) and v = (0, 1). Coefficients may be any real numbers. Which points can au + bv reach?',kind:'choice',u:[1,0],v:[0,1],options:['Only points with x ≥ 0 and y ≥ 0.','Every point in the plane, because au + bv = (a, b).','Only points where x = y.'],answer:1,hint:'Try a negative horizontal coefficient. Then think about choosing a and b separately.',solution:'au + bv = (a, b). Since a and b may be any real numbers, every point in the plane can be reached.'},
transfer:{id:'f-t',domain:'transfer',dimension:'Vectors → equations',title:'Turn movement into equations',prompt:'Which system matches a(2, −1) + b(1, 3) = (4, 5)?',kind:'choice',math:'a(2, −1) + b(1, 3) = (4, 5)',u:[2,-1],v:[1,3],target:[4,5],options:['2a + b = 4; −a + 3b = 5','2a − b = 4; a + 3b = 5','a + 2b = 4; 3a − b = 5'],answer:0,hint:'The first equation describes horizontal components. The second describes vertical components.',solution:'Horizontal: 2a + b = 4. Vertical: −a + 3b = 5. This is a different representation of the same combination.'}
};
const DOMAINS={representation:'Vector representation',addition:'Vector addition',scaling:'Scalar multiplication',combination:'Linear combinations',transfer:'Systems ↔ vectors'};
function finite(x){return typeof x==='number' && Number.isFinite(x);}
function valid(t,a){if(!a||typeof a!=='object')return false;if(['pair','drag','coeff','drag-choice'].includes(t.kind)){if(!Array.isArray(a.values)||a.values.length!==2||!a.values.every(finite))return false;if(['drag','drag-choice'].includes(t.kind)&&(!a.moved||a.values.some(v=>!Number.isInteger(v)||Math.abs(v)>6)))return false;if(t.kind==='coeff'&&(!a.touched||a.values.some(v=>Math.abs(v)>3||v*2!==Math.round(v*2))))return false;}if(['choice','drag-choice'].includes(t.kind)){if(!Number.isInteger(a.choice)||a.choice<0||a.choice>=t.options.length)return false;}return true;}
function score(t,a){if(!valid(t,a))return null;const r={};if(t.kind!=='choice')r[t.dimension]=a.values.every((x,i)=>Math.abs(x-t.answer[i])<.01);if(t.kind==='choice')r[t.dimension]=a.choice===t.answer;if(t.kind==='drag-choice')r['Meaning']=a.choice===t.choiceAnswer;return r;}
function evidence(records,domain){const obs=[];for(const t of [...TASKS,...Object.values(FOLLOWUPS)]){const r=records[t.id];if(t.domain!==domain||!r||r.status!=='submitted')continue;const s=score(t,r.answer);if(!s)continue;for(const [dimension,correct] of Object.entries(s))obs.push({id:t.id,dimension,correct,supported:!!r.supported});}const yes=obs.filter(x=>x.correct),no=obs.filter(x=>!x.correct);let state='Missing evidence';if(yes.length&&no.length)state='Conflicting evidence';else if(no.length)state='Needs another check';else if(yes.length)state=yes.every(x=>x.supported)?'Supported evidence':yes.some(x=>x.supported)?'Mixed support conditions':'Independent evidence';return{domain,name:DOMAINS[domain],state,observations:obs};}
function selectFollowups(records){return Object.keys(DOMAINS).map((domain,i)=>({domain,i,e:evidence(records,domain)})).filter(x=>!['Independent evidence','Supported evidence','Mixed support conditions'].includes(x.e.state)).sort((a,b)=>{const rank=e=>e.state==='Conflicting evidence'?0:e.state==='Needs another check'?1:2;return rank(a.e)-rank(b.e)||a.i-b.i;}).slice(0,4).map(x=>({...FOLLOWUPS[x.domain],trigger:x.e.state}));}
const api={TASKS,FOLLOWUPS,DOMAINS,valid,score,evidence,selectFollowups};root.AA012=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
